// FastAPI 서버와 통신하는 함수 모음
// 모든 HTTP 요청을 이 파일에서 관리하여 API URL 변경 시 한 곳만 수정하면 됨

import axios from "axios";

// .env의 REACT_APP_API_URL을 기본 주소로 사용
// axios 인스턴스를 만들어 baseURL을 공통 적용
const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL,
});

/**
 * 예약 생성 요청
 * @param {Object} data - { name, phone, date, time_slot }
 * @returns {Object} 생성된 예약 정보 (배정된 상담실 포함)
 * @throws 400: 주말/기간 초과/만석, 422: 유효성 검사 실패
 */
export const createReservation = async (data) => {
  const response = await api.post("/reservations", data);
  return response.data;
};
